frame.store("_a_diet_predicate", { let __signature_3443 = Signature { name: "_a_diet_predicate".into(), positional: vec!["who".into(),"diet".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3445 = Value::dict(); __attrs_3445.dict_set(Value::from("__doc__"), Value::from("A person's diet as the words after their name: \"eats fish\", \"doesn't eat meat\", \"is vegan\".\n\n    The store keeps a restriction as \"no fish\", and what somebody eats put back as \"eats fish\":\n    a take-back of a restriction is not an empty record, it is the food they eat now, so the\n    recall says \"Your son eats fish.\" where \"Your son is eats fish.\" is not a sentence.\n    "))?; __attrs_3445.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3446 = Value::dict(); __attrs_3445.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3442 = Frame::module(frame.globals.clone()); let mut __function_3444 = NativeFunction::qualified_with_origin("_a_diet_predicate".into(), "_a_diet_predicate".into(), "bot.memory.store_replies".into(), __attrs_3445, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/store_replies.py", first: 6369, last: 6383, qualname: "_a_diet_predicate" }, closure: __closure_3442.clone(), freevars: vec![] }, move |rt, args| __py_193::_a_diet_predicate(rt, __closure_3442.clone(), &__signature_3443, args)); __function_3444 })?;
