frame.store("_no_diet", { let __signature_3453 = Signature { name: "_no_diet".into(), positional: vec!["who".into()], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_3455 = Value::dict(); __attrs_3455.dict_set(Value::from("__doc__"), Value::from("An ask about how someone else eats when nothing food-shaped is kept for them.\n\n    Saying \"you haven't told me what your dad eats\" on its own is true and cold, and it is what\n    someone with a diabetic dad gets. The offer is the part that helps: the fact is one line away.\n\n    A baby is left to the weaning answers: the store keeps the age, and \"my baby is 7 months what\n    can she eat\" is a question about that age, not about a diet the store has never heard.\n    "))?; __attrs_3455.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_3456 = Value::dict(); __attrs_3455.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_3452 = Frame::module(frame.globals.clone()); let mut __function_3454 = NativeFunction::qualified_with_origin("_no_diet".into(), "_no_diet".into(), "bot.memory.store_replies".into(), __attrs_3455, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/memory/store_replies.py", first: 6400, last: 6412, qualname: "_no_diet" }, closure: __closure_3452.clone(), freevars: vec![] }, move |rt, args| __py_195::_no_diet(rt, __closure_3452.clone(), &__signature_3453, args)); __function_3454 })?;
